paths=["benchmark/preparation-status.json","benchmark/sources.md","benchmark/preparation.json","docs/research/0002-coverage.md","docs/perpetua/environment.md",".session/history/manifest.json"]
for name in paths:
 print("FILE "+name)
 p=Path(name)
 if p.exists():
  for n,line in enumerate(p.read_text().splitlines(),1): print(str(n)+": "+line)
 else: print("MISSING")
for args in [["git","rev-parse","HEAD"],["git","status","--short"],["git","log","-8","--format=%H %s","--","benchmark","docs/research/0002-coverage.md"]]:
 result=subprocess.run(args,text=True,capture_output=True); print("COMMAND "+repr(args)+" EXIT "+str(result.returncode)); print(result.stdout); print(result.stderr)'

