for name in ["benchmark/scripts/sources.py","docs/research/scripts/coverage/inventory.py"]:
 print("FILE "+name)
 for n,line in enumerate(Path(name).read_text().splitlines(),1): print(str(n)+": "+line)
p=Path("benchmark/sources.json"); raw=p.read_text(); data=json.loads(raw)
print("MANIFEST TOP-LEVEL KEYS",list(data))
for key,value in data.items():
 if key != "artifacts": print("FIELD "+key+" "+json.dumps(value,ensure_ascii=False))
